// Remote commands are queued before heartbeat telemetry reflects them. Retain each
// selection until readback confirms it, a request fails, or its bounded grace period ends.
export function effectSelections(now = Date.now) {
	const edits = new Map();
	return {
		select(target, fx, devices) {
			const selection = devices.filter((device) => target === "all" || device.id === target)
				.map((device) => ({ id: device.id, fx, until: Infinity }));
			for (const edit of selection) edits.set(edit.id, edit);
			return selection;
		},
		sent(selection = []) {
			for (const edit of selection) if (edits.get(edit.id) === edit) edit.until = now() + 8000;
		},
		failed(selection = []) {
			for (const edit of selection) if (edits.get(edit.id) === edit) edits.delete(edit.id);
		},
		reconcile(devices) {
			const ids = new Set(devices.map((device) => device.id));
			for (const id of edits.keys()) if (!ids.has(id)) edits.delete(id);
			return devices.map((device) => {
				const edit = edits.get(device.id);
				if (!edit) return device;
				if ((device.lightingKnown && device.fx === edit.fx) || now() >= edit.until) {
					edits.delete(device.id);
					return device;
				}
				return { ...device, fx: edit.fx };
			});
		},
		waiting: () => edits.size > 0,
	};
}
